		if (notNull) {
			stage.destroySilently();
			remove(stage, true);
		}

		cameraFocusOffset.put();

		scripts = FlxDestroyUtil.destroy(scripts);

		super.destroy();

		WindowUtils.resetAffixes();
		SaveWarning.reset();

		instance = null;

		Note.__customNoteTypeExists = [];
	}

